const { cliente_id, telefone, args = {} } = $json;
const placa = String(args.placa ?? '').toUpperCase().replace(/[^A-Z0-9]/g, '');
const modelo = String(args.modelo ?? '').trim();
const servico = String(args.servico ?? '').trim();
const data = String(args.data ?? '').trim();
const hora = String(args.hora ?? '').trim();
if (!/^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$/.test(placa)) return [{ json: { invalido: true, motivo: 'placa_invalida' } }];
if (!modelo) return [{ json: { invalido: true, motivo: 'modelo_obrigatorio' } }];
if (!servico) return [{ json: { invalido: true, motivo: 'servico_obrigatorio' } }];
if (!/^\d{4}-\d{2}-\d{2}$/.test(data)) return [{ json: { invalido: true, motivo: 'data_invalida' } }];
if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(hora)) return [{ json: { invalido: true, motivo: 'hora_invalida' } }];
return [{ json: { cliente_id, telefone, placa, modelo, servico, data, hora } }];

const entrada = $('Validar args').item.json;
if (entrada.invalido) {
  const msgs = {
    placa_invalida: 'Não entendi a placa. Pode mandar de novo?',
    modelo_obrigatorio: 'Qual o modelo do carro?',
    servico_obrigatorio: 'Qual serviço você quer fazer?',
    data_invalida: 'Não entendi o dia. Pode mandar no formato dia/mês?',
    hora_invalida: 'Não entendi o horário. Pode mandar tipo 09:00?'
  };
  return [{ json: { texto: msgs[entrada.motivo] ?? 'Faltou algum dado pro agendamento.', dados: { erro: entrada.motivo } } }];
}
if ($json.erro) {
  const texto = $json.erro === 'horario_indisponivel'
    ? 'Esse horário não tá livre. Quer tentar outro?'
    : 'Não consegui agendar agora. Quer que eu chame um atendente?';
  return [{ json: { texto, dados: { erro: $json.erro } } }];
}
const texto = `Fechou! ${entrada.servico} agendado pra ${entrada.data} às ${entrada.hora}, placa ${entrada.placa}.`;
return [{ json: { texto, dados: { agendamento_id: $json.agendamento_id ?? null, placa: entrada.placa, modelo: entrada.modelo, servico: entrada.servico, data: entrada.data, hora: entrada.hora } } }];
